def eulerian_num(n, m): 
	if (m >= n or n == 0): 
		return 0 
	if (m == 0):
		return 1
	if (m == 1): 
		return 1 
	dp = [[0] * n for _ in range(n + 1)]
	dp[1][0] = 1
	for i in range(2, n + 1):
		for j in range(i):
			dp[i][j] = (j + 1) * dp[i-1][j] + (i - j) * dp[i-1][j-1]
	return dp[n][m]

