def get_total_number_of_sequences(m,n): 
	T = [[0 for _ in range(n + 1)] for _ in range(m + 1)] 
	for i in range(1, m + 1):
		T[i][1] = 1
	for j in range(2, n + 1):
		for i in range(1, m + 1):
			sum_prev = 0
			for k in range(1, i // 2 + 1):
				sum_prev += T[k][j - 1]
			T[i][j] = sum_prev
	return sum(T[i][n] for i in range(1, m + 1))

