			if i==0 or j==0:
				T[i][j]=0
			elif i > m:
				T[i][j]=0
			elif j==1:
				T[i][j]=i
			else:
				T[i][j]=T[i-1][j]+T[i//2][j-1]
	return sum(T[i][n] for i in range(1, m+1))

