def count_Primes_nums(n):
    ctr = 0
    for num in range(n):
        if num < 2:
            continue
        is_prime = True
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            ctr += 1
    return ctr

